from flask import Blueprint, request, jsonify
from sqlalchemy.exc import SQLAlchemyError
from app.models.problem import Problem
from app.database import db_session

problem_controller = Blueprint('problem_controller', __name__)

@problem_controller.route('/problems', methods=['GET'])
def get_problems():
    try:
        problems = db_session.query(Problem).all()
        return jsonify([problem.to_dict() for problem in problems]), 200
    except SQLAlchemyError as e:
        return jsonify({'error': str(e)}), 500

@problem_controller.route('/problems/<int:problem_id>', methods=['GET'])
def get_problem(problem_id):
    try:
        problem = db_session.query(Problem).filter_by(id=problem_id).first()
        if problem:
            return jsonify(problem.to_dict()), 200
        else:
            return jsonify({'error': 'Problem not found'}), 404
    except SQLAlchemyError as e:
        return jsonify({'error': str(e)}), 500

@problem_controller.route('/problems', methods=['POST'])
def create_problem():
    try:
        data = request.json
        new_problem = Problem(title=data['title'],
                              description=data['description'],
                              difficulty=data['difficulty'])
        db_session.add(new_problem)
        db_session.commit()
        return jsonify(new_problem.to_dict()), 201
    except SQLAlchemyError as e:
        db_session.rollback()
        return jsonify({'error': str(e)}), 500

@problem_controller.route('/problems/<int:problem_id>', methods=['PUT'])
def update_problem(problem_id):
    try:
        data = request.json
        problem = db_session.query(Problem).filter_by(id=problem_id).first()
        if problem:
            problem.title = data.get('title', problem.title)
            problem.description = data.get('description', problem.description)
            problem.difficulty = data.get('difficulty', problem.difficulty)
            db_session.commit()
            return jsonify(problem.to_dict()), 200
        else:
            return jsonify({'error': 'Problem not found'}), 404
    except SQLAlchemyError as e:
        db_session.rollback()
        return jsonify({'error': str(e)}), 500

@problem_controller.route('/problems/<int:problem_id>', methods=['DELETE'])
def delete_problem(problem_id):
    try:
        problem = db_session.query(Problem).filter_by(id=problem_id).first()
        if problem:
            db_session.delete(problem)
            db_session.commit()
            return jsonify({'message': 'Problem deleted successfully'}), 200
        else:
            return jsonify({'error': 'Problem not found'}), 404
    except SQLAlchemyError as e:
        db_session.rollback()
        return jsonify({'error': str(e)}), 500

from flask import Blueprint, request, jsonify
from sqlalchemy.exc import SQLAlchemyError
from app.models.user import User
from app.database import db_session

user_controller = Blueprint('user_controller', __name__)

@user_controller.route('/users/<int:user_id>', methods=['GET'])
def get_user_profile(user_id):
    try:
        user = db_session.query(User).filter(User.id == user_id).one_or_none()
        if user is None:
            return jsonify({'error': 'User not found'}), 404
        return jsonify(user.to_dict()), 200
    except SQLAlchemyError as e:
        return jsonify({'error': str(e)}), 500

@user_controller.route('/users', methods=['POST'])
def create_user_profile():
    data = request.json
    try:
        new_user = User(
            username=data.get('username'),
            email=data.get('email'),
            password=data.get('password')  # Assume password is hashed before saving
        )
        db_session.add(new_user)
        db_session.commit()
        return jsonify(new_user.to_dict()), 201
    except SQLAlchemyError as e:
        db_session.rollback()
        return jsonify({'error': str(e)}), 500

@user_controller.route('/users/<int:user_id>', methods=['PUT'])
def update_user_profile(user_id):
    data = request.json
    try:
        user = db_session.query(User).filter(User.id == user_id).one_or_none()
        if user is None:
            return jsonify({'error': 'User not found'}), 404
        user.username = data.get('username', user.username)
        user.email = data.get('email', user.email)
        if data.get('password'):
            user.password = data.get('password')  # Assume password is hashed before saving
        db_session.commit()
        return jsonify(user.to_dict()), 200
    except SQLAlchemyError as e:
        db_session.rollback()
        return jsonify({'error': str(e)}), 500

@user_controller.route('/users/<int:user_id>', methods=['DELETE'])
def delete_user_profile(user_id):
    try:
        user = db_session.query(User).filter(User.id == user_id).one_or_none()
        if user is None:
            return jsonify({'error': 'User not found'}), 404
        db_session.delete(user)
        db_session.commit()
        return jsonify({'message': 'User deleted successfully'}), 200
    except SQLAlchemyError as e:
        db_session.rollback()
        return jsonify({'error': str(e)}), 500

from flask import Blueprint, jsonify, request
from sqlalchemy.orm import Session
from app.models.leaderboard import Leaderboard
from app.database import get_db

leaderboard_bp = Blueprint('leaderboard', __name__)

@leaderboard_bp.route('/leaderboard', methods=['GET'])
def get_leaderboard():
    db: Session = get_db()
    try:
        leaderboard_entries = db.query(Leaderboard).order_by(Leaderboard.score.desc()).all()
        return jsonify([entry.to_dict() for entry in leaderboard_entries]), 200
    except Exception as e:
        return jsonify({'error': str(e)}), 500

@leaderboard_bp.route('/leaderboard/<int:user_id>', methods=['GET'])
def get_user_leaderboard_entry(user_id):
    db: Session = get_db()
    try:
        entry = db.query(Leaderboard).filter(Leaderboard.user_id == user_id).first()
        if entry:
            return jsonify(entry.to_dict()), 200
        else:
            return jsonify({'error': 'User not found in leaderboard'}), 404
    except Exception as e:
        return jsonify({'error': str(e)}), 500

@leaderboard_bp.route('/leaderboard', methods=['POST'])
def add_leaderboard_entry():
    db: Session = get_db()
    data = request.json
    try:
        new_entry = Leaderboard(user_id=data['user_id'], score=data['score'])
        db.add(new_entry)
        db.commit()
        return jsonify(new_entry.to_dict()), 201
    except Exception as e:
        db.rollback()
        return jsonify({'error': str(e)}), 500

@leaderboard_bp.route('/leaderboard/<int:user_id>', methods=['PUT'])
def update_leaderboard_entry(user_id):
    db: Session = get_db()
    data = request.json
    try:
        entry = db.query(Leaderboard).filter(Leaderboard.user_id == user_id).first()
        if entry:
            entry.score = data.get('score', entry.score)
            db.commit()
            return jsonify(entry.to_dict()), 200
        else:
            return jsonify({'error': 'User not found in leaderboard'}), 404
    except Exception as e:
        db.rollback()
        return jsonify({'error': str(e)}), 500

@leaderboard_bp.route('/leaderboard/<int:user_id>', methods=['DELETE'])
def delete_leaderboard_entry(user_id):
    db: Session = get_db()
    try:
        entry = db.query(Leaderboard).filter(Leaderboard.user_id == user_id).first()
        if entry:
            db.delete(entry)
            db.commit()
            return jsonify({'message': 'Entry deleted successfully'}), 200
        else:
            return jsonify({'error': 'User not found in leaderboard'}), 404
    except Exception as e:
        db.rollback()
        return jsonify({'error': str(e)}), 500

